#!/usr/bin/env python3
"""Prepare local Bootstrap JS/CSS and scope the CSS. Requires tinycss2==1.4.0."""
from pathlib import Path
import re
import tinycss2
ROOT=Path(__file__).resolve().parent.parent
SCOPE='.tr-bootstrap'
def strip_source_map(text):
    # Debug maps are not shipped; do not advertise missing files to DevTools.
    return re.sub(r'(?m)^//# sourceMappingURL=[^\r\n]*|/\*# sourceMappingURL=[^\r\n]*?\*/','',text)

def selector(text):
    text=text.strip()
    if text.startswith('.modal-backdrop'):return 'body > '+text
    if text.startswith(':root'):return SCOPE+text[5:]
    if text.startswith('[data-bs-theme='):return SCOPE+text
    for tag in ('html','body'):
        if re.match(r'^'+tag+r'(?=$|[\s\[.:#>+~])',text):return SCOPE+text[len(tag):]
    return SCOPE+' '+text

def render(rules,keyframes=False):
    out=[]
    for rule in rules:
        if rule.type=='qualified-rule':
            if keyframes:out.append(tinycss2.serialize([rule]));continue
            groups=[];group=[]
            for token in rule.prelude:
                if token.type=='literal' and token.value==',':groups.append(selector(tinycss2.serialize(group)));group=[]
                else:group.append(token)
            groups.append(selector(tinycss2.serialize(group)))
            out.append(','.join(groups)+'{'+tinycss2.serialize(rule.content)+'}')
        elif rule.type=='at-rule' and rule.content is not None and rule.lower_at_keyword in ('media','supports','container','layer','keyframes','-webkit-keyframes'):
            out.append('@'+rule.at_keyword+tinycss2.serialize(rule.prelude)+'{'+render(tinycss2.parse_rule_list(rule.content),rule.lower_at_keyword.endswith('keyframes'))+'}')
        elif rule.type=='error':raise ValueError(rule.message)
        else:out.append(tinycss2.serialize([rule]))
    return ''.join(out)
if __name__=='__main__':
    directory=ROOT/'themes/tape-room/assets/bootstrap'
    for name in ('bootstrap.min.css','bootstrap.bundle.min.js'):
        path=directory/name
        original=path.read_text()
        cleaned=strip_source_map(original)
        if cleaned!=original:path.write_text(cleaned)
    css=render(tinycss2.parse_stylesheet((directory/'bootstrap.min.css').read_text()))
    css=strip_source_map(css)
    (directory/'bootstrap.scoped.css').write_text('/* Bootstrap 5.3.8; generated by tools/build-tape-room-bootstrap.py. */\n'+css+'\n')
    print('Built isolated Bootstrap CSS.')
